insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todas as peças do inquérito policial serão, num só processado, reduzidas a escrito ou datilografadas e, neste caso, rubricadas pela autoridade.', '["Peças do inquérito reunidas em um só processado.","Reduzidas a escrito ou datilografadas.","Se datilografadas, rubricadas pela autoridade."]'::jsonb, '["Regra de forma do inquérito; na prática, usa-se o meio digital."]'::jsonb, 'Os termos e depoimentos do inquérito são reunidos e rubricados pelo delegado.', '["Assertiva que dispensa a rubrica da autoridade nas peças datilografadas erra."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-9'
