insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O inquérito deverá terminar no prazo de 10 dias, se o indiciado tiver sido preso em flagrante ou estiver preso preventivamente (contado, nesta hipótese, do dia em que se executar a ordem de prisão), ou no prazo de 30 dias, quando estiver solto, mediante fiança ou sem ela. A autoridade fará minucioso relatório do que apurou e enviará os autos ao juiz competente, podendo indicar testemunhas não inquiridas. Quando o fato for de difícil elucidação e o indiciado estiver solto, a autoridade pode requerer ao juiz a devolução dos autos para ulteriores diligências no prazo marcado pelo juiz.', '["Preso: 10 dias.","Solto: 30 dias, com ou sem fiança.","§1º: relatório minucioso e remessa ao juiz competente.","§2º: pode indicar testemunhas não inquiridas.","§3º: fato de difícil elucidação, indiciado solto: devolução dos autos para novas diligências."]'::jsonb, '["Em preventiva, o prazo conta do cumprimento da ordem de prisão.","Em leis especiais, os prazos podem ser diferentes."]'::jsonb, 'Indiciado preso em flagrante: inquérito conclui em 10 dias.', '["Assertiva que fixa em 30 dias o prazo do inquérito com indiciado preso erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 3º-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os instrumentos do crime, bem como os objetos que interessarem à prova, acompanharão os autos do inquérito.', '["Instrumentos do crime acompanham os autos.","Objetos de interesse para a prova também."]'::jsonb, '["Relaciona-se à cadeia de custódia da prova."]'::jsonb, 'A arma usada no crime é encaminhada junto com os autos do inquérito.', '["Assertiva que determina o descarte dos instrumentos do crime após o inquérito erra: eles acompanham os autos."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-11'
