insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o ofendido for menor de 18 anos, ou mentalmente enfermo, ou retardado mental, e não tiver representante legal, ou colidirem os interesses deste com os daquele, o direito de queixa poderá ser exercido por curador especial, nomeado, de ofício ou a requerimento do Ministério Público, pelo juiz competente para o processo penal.', '["Ofendido menor de 18 anos ou incapaz, sem representante legal ou com interesses colidentes.","Curador especial exerce o direito de queixa.","Nomeado de ofício ou a requerimento do MP pelo juiz competente."]'::jsonb, '["Hipótese de conflito de interesses com o representante."]'::jsonb, 'Menor ofendido cujo representante é o autor do crime: nomeia-se curador especial.', '["Assertiva que impede o exercício da queixa por menor sem representante erra: nomeia-se curador especial."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
