insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não obstante a sentença absolutória no juízo criminal, a ação civil pode ser proposta quando não tiver sido, categoricamente, reconhecida a inexistência material do fato.', '["Absolvição criminal não impede a ação civil.","Exceção: reconhecimento categórico da inexistência material do fato."]'::jsonb, '["Absolvição por falta de provas não impede a ação civil."]'::jsonb, 'Réu absolvido por falta de provas ainda pode ser demandado no cível.', '["Assertiva que impede a ação civil após qualquer absolvição criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 65","Art. 386"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-66'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não impedirão igualmente a propositura da ação civil o despacho de arquivamento do inquérito ou das peças de informação; a decisão que julgar extinta a punibilidade; e a sentença absolutória que decidir que o fato imputado não constitui crime.', '["Arquivamento do inquérito não impede a ação civil.","Extinção da punibilidade não impede a ação civil.","Sentença absolutória por fato atípico não impede a ação civil."]'::jsonb, '["Independência relativa entre as esferas."]'::jsonb, 'Inquérito arquivado: a vítima ainda pode pedir indenização no cível.', '["Assertiva que impede a ação civil após o arquivamento do inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-67'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
